```java
// Vulnerable code: SQL injection due to unsanitized user input
protected void doGet(HttpServletRequest request, HttpServletResponse response) {
    String username = request.getParameter("username");
    try {
        Connection conn = DriverManager.getConnection(DB_URL);
        // Directly concatenating user input into query
        String query = "SELECT * FROM users WHERE username = '" + username + "'";
        Statement stmt = conn.createStatement();
        ResultSet rs = stmt.executeQuery(query); // Executes potentially malicious SQL
    } catch (SQLException e) {
        e.printStackTrace();
    }
}
```

***
```java
// Fixed code: Uses PreparedStatement to prevent SQL injection
protected void doGet(HttpServletRequest request, HttpServletResponse response) {
    String username = request.getParameter("username");
    try {
        Connection conn = DriverManager.getConnection(DB_URL);
        // Parameterized query safely handles user input
        PreparedStatement stmt = conn.prepareStatement("SELECT * FROM users WHERE username = ?");
        stmt.setString(1, username); // Input is properly sanitized
        ResultSet rs = stmt.executeQuery();
    } catch (SQLException e) {
        e.printStackTrace();
    }
}
```

